CH={  # geänderte vorhandene Texte: m_chal_d, sw_unchecked
'de':("Zielfahren, Wandziel, Max. und Min. Distanz","Der Kartendienst für Zielorte hat nicht geantwortet. Das Ziel ist deshalb eine freie Landezone am berechneten Punkt; ob dort ein Gewässer oder ein gesperrter Ort liegt, wurde nicht geprüft."),
'en':("Target flight, Wandziel, max. and min. distance","The map service for target sites did not answer. The target is therefore a free landing zone at the computed point; it was not checked for water or restricted places."),
'fr':("Vol sur cible, Wandziel, distance max. et min.","Le service cartographique des lieux cibles n’a pas répondu. La cible est donc une zone d’atterrissage libre au point calculé ; la présence d’eau ou de lieux interdits n’a pas été vérifiée."),
'pl':("Lot do celu, Wandziel, maks. i min. odległość","Usługa mapowa dla miejsc celu nie odpowiedziała. Celem jest więc swobodna strefa lądowania w obliczonym punkcie; nie sprawdzono, czy jest tam woda lub miejsce zastrzeżone."),
'cs':("Let na cíl, Wandziel, max. a min. vzdálenost","Mapová služba pro cílová místa neodpověděla. Cílem je proto volná přistávací zóna ve vypočteném bodě; nebylo ověřeno, zda tam není voda nebo zakázané místo."),
'zh-TW':("目標飛行、Wandziel、最大與最小距離","目標地點的地圖服務沒有回應。因此目標是計算點上的自由降落區，未檢查該處是否有水域或禁區。"),
'es':("Vuelo al objetivo, Wandziel, distancia máx. y mín.","El servicio de mapas para lugares objetivo no respondió. Por eso el objetivo es una zona de aterrizaje libre en el punto calculado; no se comprobó si hay agua o lugares restringidos."),
}
order=['de','en','fr','pl','cs','zh-TW','es']; pos=[]
for c in order:
    key="\n'"+c+"':{" if s.count("\n'"+c+"':{")==1 else "\n"+c+":{"
    assert s.count(key)==1,(c,s.count(key)); pos.append(s.index(key))
pos.append(s.index("\n};",pos[-1])); out=s[:pos[0]]
for i,c in enumerate(order):
    seg=s[pos[i]:pos[i+1]]
    seg,n1=re.subn(r"m_chal_d:'[^']*'", lambda m:"m_chal_d:'"+CH[c][0]+"'", seg); seg,n2=re.subn(r"sw_unchecked:'[^']*'", lambda m:"sw_unchecked:'"+CH[c][1]+"'", seg); assert n1==1 and n2==1,(c,n1,n2)
    if c=='de':
        seg,n3=re.subn(r"task_target:'[^']*'", "task_target:'Zielfahren'", seg); assert n3==1
        seg,n4=re.subn(r"task_target_d:'[^']*'", "task_target_d:'Lande so nah wie möglich am Ziel. Es liegt je nach Stufe rund 2 bis 3 km, 5 km oder 10 km entfernt.'", seg); assert n4==1
    assert "'" not in NEW[c].replace("', ","").replace(":'","").rstrip(",").rstrip("'"), c   # keine losen Hochkommas in den Texten
    k=seg.index(" toast_valve:"); seg=seg[:k]+" "+NEW[c]+seg[k:]; out+=seg
f.s=out+s[pos[-1]:]
f.rep("function tr(k, p){ let s = TX[UI.lang][k] ?? TX.en[k] ?? TX.de[k] ?? k; if (p) for (const q in p) s = s.replace('{' + q + '}', p[q]); return s; }",
      "function tr(k, p){ let s = TX[UI.lang][k] ?? TX.en[k] ?? TX.de[k] ?? k; if (p) for (const q in p) s = s.split('{' + q + '}').join(p[q]); return s; }")
f.save(); print('ok')
